<template><div class="simple"><div class="app-card card"><AppLogo/><h1>创建账号</h1><form @submit.prevent="submit"><input v-model="form.username" class="input" placeholder="用户名"/><input v-model="form.password" class="input" type="password" placeholder="密码"/><div v-if="msg" :class="ok?'ok':'err'">{{msg}}</div><button class="btn btn-primary">注册</button></form><RouterLink to="/login" class="back">已有账号，返回登录</RouterLink></div></div></template>
<script setup>import {reactive,ref} from 'vue';import AppLogo from '../components/common/AppLogo.vue';import {useAuthStore} from '../stores/auth.js';const form=reactive({username:'',password:''}),msg=ref(''),ok=ref(false),auth=useAuthStore();async function submit(){try{await auth.register(form);ok.value=true;msg.value='注册成功，请返回登录'}catch(e){ok.value=false;msg.value=e.message}}</script>
<style scoped>.simple{min-height:100vh;display:grid;place-items:center;padding:24px}.card{width:min(420px,100%);padding:30px}.card h1{font-size:22px;margin:26px 0 20px}form{display:grid;gap:12px}.back{display:block;margin-top:18px;text-align:center;color:var(--primary);font-size:12px}.ok{color:var(--success);font-size:12px}.err{color:var(--danger);font-size:12px}</style>
